import{_ as e,c as p,o as t,ah as r}from"./chunks/framework.Dnh4IO1K.js";const d=JSON.parse('{"title":"46、【升】 巽下坤上","description":"周易闡真 - 46、【升】 巽下坤上","frontmatter":{"title":"46、【升】 巽下坤上","description":"周易闡真 - 46、【升】 巽下坤上"},"headers":[],"relativePath":"classics/chanzhen/047.md","filePath":"classics/chanzhen/047.md"}'),s={name:"classics/chanzhen/047.md"};function n(c,a,i,o,l,h){return t(),p("div",null,[...a[0]||(a[0]=[r('<blockquote><p>彖曰：柔以時升，巽而順，剛中而應，是以大亨，用見大人勿恤，有慶也。南征吉，志行也。</p></blockquote><h1 id="_46、【升】-巽下坤上" tabindex="-1">46、【升】 巽下坤上 <a class="header-anchor" href="#_46、【升】-巽下坤上" aria-label="Permalink to “46、【升】 巽下坤上”">​</a></h1><p>初六：允升，大吉。</p><p>九二：孚乃利用禴，無咎。</p><p>九三：升虛邑。</p><p>六四：王用亨於岐山，吉，無咎。</p><p>六五：貞吉，升階。</p><p>上六：冥升，利於不息之貞。</p><h2 id="孔易闡真-​" tabindex="-1">孔易闡真 ​ <a class="header-anchor" href="#孔易闡真-​" aria-label="Permalink to “孔易闡真 ​”">​</a></h2><p>大象：地中生木，升。君子以順德，積小以高大。</p><p>升者，增升也。上坤地，下巽木，是地中生木也。木自地中而生，漸次出地，升之象也。</p><p>君子有見於此，知人之不能高大其德者，皆由不知順其德而悖其德。不順其德，舍其近而求其遠，懸虛不實，永無增升之日。以是順德，積小以高大焉。積者，高之漸；小者，大之由。順時順理，是謂順德。能順其德，防微杜漸，戒慎恐懼，小善必為，微惡必去，愈久愈力，工夫不缺，日積日多，自小而漸至於高大；亦如地中生木，始而在地中，漸而出地外，又漸而幹立枝盛，又漸而高大成材。高大之材，豈一朝一夕之功哉?一切學人，不肯下實落工夫，方才進步，便想成道，未曾入門，即欲入室。如此存心，是不順德而順欲，焉能到得高大之處?卦象坤巽合成，漸進而順行，所謂深造自得者，不在此乎?</p><h2 id="悟元子註解-​" tabindex="-1">悟元子註解 ​ <a class="header-anchor" href="#悟元子註解-​" aria-label="Permalink to “悟元子註解 ​”">​</a></h2><p>用亨，亨作享。冥，音明。</p><p>升者，自卑登高之義。卦德上坤順，下巽入，徐緩進步，順時而行，不即不離，漸入真常，故謂升。此謹慎火候之卦，承上姤卦而來。姤者，巽入於健，陽極陰生，邪氣日進，正氣日退，習染成性，漸入下愚不移之地矣。所以者何?因其陽失其健，陰亦不順耳。</p><p>金丹大道，未復其陽，先順其陰，陰若一順，則人慾不生，正念常存，循序漸進，可以自無而至有，自虛而至實，下學上達，明善復初而無難，故升有元亨之道也。但此元亨之升，乃竊陰陽，奪造化，超凡入聖之事，其中火候細微，工程悠遠，非一切妄猜私議，盲修瞎煉者所能行，必須真師口傳心授，真知確見，方能一直前行，無阻無擋，是以用升之道，利於見大人也。大人，即完成大道之聖人。蓋大人成己成物，一言一語，俱有道理。如風之無物不入，能以開人之智慧；如地之無物不長，能以救人之災殃。見大人而後用之，則藥物得真，火候有準，可以勿恤，嚮明遠行，一步有一步之益，一日有一日之功，自卑登高，由淺及深，終必進於聖賢之域，其吉為何如乎?</p><p>初六，性柔志剛，虛心自下，親近有道之士，而高明者，未有不允其升，不授其真者。此柔而順剛之升也。</p><p>九二，剛而有得於中，深明藥物火候，以誠而入，以柔而用，漸次下功，如以禴祭神，用誠感通，必升於一無所咎之地矣。此剛而用柔之升也。</p><p>九三，予聖自雄，不知尋師訪友，妄猜私議，冒然前進，欲向其前，反落於後，如升於虛邑，何能進於高明之地?此不知求師之升也。</p><p>六四，柔而守正，順時進步，煉己持心，自卑登高，漸入佳境，如王用享於岐山，未有不升於上者。此吉而無咎之升也。</p><p>六五，虛人心而求道心，虛心即能實腹。所謂一念回機，如同本得，其增益道德，如升階之易。此柔而虛心之升也。</p><p>上六，愚而自用，執著一己之陰，妄想增升道德，了命了性，升之不息，冥之不息，愈升愈冥，焉能出晦暗而進於高明?若欲升之不冥，必須求師口訣，利於不息之貞，懲忿窒欲，閒邪存誠，愈久愈力，亦可升於明善復初之地。此柔而歸正之升也。</p><p>升之為道，以剛道而行柔道也。卦德巽而順行，外柔內剛，循序漸進，不急不緩，深造自得，未有不升於聖賢之堂奧者。然火候之秘，總要真師口傳心授。《彖》曰：“用見大人，勿恤，南征吉。”可以知矣。</p>',23)])])}const m=e(s,[["render",n]]);export{d as __pageData,m as default};
